        const updateOrder = buildPldUpdateOrderByParent(pldMotion.pldInfo);
        if (updateOrder.length < 1) return;
        pldMotion.pldInfo.updateOrder = updateOrder;
        pldMotion.pldInfo.forEach((pld)=>{
            pld.updateOrder = updateOrder;
        });
